const fs=require('fs'),vm=require('vm');
const html=fs.readFileSync('index.html','utf8');
const code=html.match(/<script>([\s\S]*?)<\/script>/)[1];
const nodes={};for(const m of html.matchAll(/id="([^"]+)"/g))nodes[m[1]]={hidden:false,style:{},classList:{remove(){},add(){}},setAttribute(){},replaceChildren(){},addEventListener(){},focus(){},showModal(){},close(){}};
const context={document:{getElementById:id=>{if(!nodes[id])throw Error('Missing '+id);return nodes[id]},querySelector:()=>({}),createElement:()=>({})},location:{hash:''},window:{addEventListener(){},scrollTo(){}},console};
vm.createContext(context);vm.runInContext(code,context);
if(nodes.lineup.hidden||!nodes['film-view'].hidden)throw Error('Home visibility');
if((nodes['session-list'].innerHTML.match(/class="session-link"/g)||[]).length!==3)throw Error('Schedule count');
for(let i=1;i<=3;i++){context.location.hash='#film-'+i;vm.runInContext('route(false)',context);if(!nodes.lineup.hidden||nodes['film-view'].hidden||!nodes.poster.innerHTML.includes('<svg'))throw Error('Detail '+i);console.log('Detail '+i+': '+nodes.title.textContent+' / '+nodes.time.textContent)}
